const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');
const mk = () => new DocumentRepository([
  { id: 'own', tenant: 'a', owner: 'e', deleted: false, archived: false },
  { id: 'other', tenant: 'a', owner: 'x', deleted: false, archived: false },
  { id: 'del', tenant: 'a', owner: 'e', deleted: true, archived: false },
  { id: 'foreign', tenant: 'b', owner: 'e', deleted: false, archived: false },
  { id: 'done', tenant: 'a', owner: 'x', deleted: false, archived: true },
]);
const repo = mk(); const s = new DocumentService(repo);
const A = r => ({ tenant: 'a', user: r + '1', role: r }); const E = { tenant: 'a', user: 'e', role: 'editor' };
for (const id of ['missing', 'del', 'foreign']) assert.throws(() => s.archive(A('admin'), id), /not found/);
assert.throws(() => s.archive(A('viewer'), 'own'), /forbidden/);
assert.throws(() => s.archive(E, 'other'), /forbidden/);
assert.throws(() => s.archive(E, 'done'), /forbidden/);
assert.throws(() => s.archive(A('viewer'), 'done'), /forbidden/);
assert.equal(repo.audit.length, 0);
assert.ok(repo.documents.filter(d => d.id !== 'done').every(d => !d.archived));
s.archive(E, 'own'); s.archive(A('admin'), 'other'); s.archive(A('admin'), 'done');
assert.deepEqual(repo.audit, [{ actor: 'e', document: 'own' }, { actor: 'admin1', document: 'other' }]);

